#include <gc.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

/* Guest entry generated by Cranelift emit. Defined in the guest object. */
int32_t shin_entry(void);

/* Single allocation entry point (Boehm GC wrapper). */
void *shin_alloc(size_t size) { return GC_malloc(size); }

/* Int print used by the guest entry. */
void shin_print_int(int64_t v) {
  printf("%lld\n", (long long)v);
  fflush(stdout);
}

int main(void) {
  GC_INIT();
  return shin_entry();
}
